.decomp-action{display:inline-flex;align-items:center;justify-content:center;padding:10px 14px;border:1px solid var(--line-2);border-radius:2px;background:var(--surface);color:var(--ink);text-decoration:none;font-weight:700;font-size:13px;justify-self:start}
.decomp-action:hover{border-color:var(--ink)}
.decomp-layer{display:grid;gap:8px}
.decomp-layer>h4{border-bottom:1px solid var(--line);padding-bottom:7px}
.decomp-item{border-bottom:1px solid var(--line);padding:0 0 10px;display:grid;gap:4px}
.decomp-top{display:flex;flex-wrap:wrap;gap:7px;align-items:center}
.decomp-top a{font-weight:700;text-decoration:none}
.decomp-top a:hover{text-decoration:underline}
.decomp-top code{font:500 11px var(--f-mono);color:var(--muted)}
.decomp-level{display:inline-block;padding:1px 6px;border:1px solid var(--ink-2);border-radius:2px;font-size:10px;font-weight:700;color:var(--ink-2)}
.decomp-level.explicit{background:var(--ink-2);color:var(--surface)}
.decomp-evidence{font:11px/1.5 var(--f-mono);color:var(--muted);margin:0;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;overflow-wrap:anywhere}
.decomp-item details[open] .decomp-evidence{display:block}
.decomp-item summary{cursor:pointer;font:11px var(--f-mono);color:var(--muted)}

var CASE_DATA = JSON.parse(document.getElementById('case-data').textContent);
var CASE_BY_ID = {};
CASE_DATA.cases.forEach(function(c){ CASE_BY_ID[c.id] = c; });

function breakdownPanel(it){
  var p = $('#panel-breakdown'); p.textContent = '';
  var c = CASE_BY_ID[it.id];
  if (!c) { p.append(h('p', { class: 'fine', text: '这条尚无关键词拆解。' })); return; }
  p.append(h('a', { class: 'decomp-action', href: c.recipe_link, target: '_blank', rel: 'noopener' }, '在词典中用这套配方 ↗'));
  p.append(h('p', { class: 'fine', text: '明写：提示词直接表达；隐含：依据原文推断。点关键词可在新标签查看词义与演示。' }));
  ['L1','L2','L3','L4','L5'].forEach(function(layer){
    var tags = c.tags.filter(function(t){ return t.layer === layer; });
    if (!tags.length) return;
    var names = {L1:'底座',L2:'质感',L3:'运动',L4:'交互',L5:'结构'};
    var group = h('section', { class: 'decomp-layer' }, h('h4', { text: layer + ' · ' + names[layer] + ' · ' + tags.length + ' 词' }));
    tags.forEach(function(t){
      var name = CASE_DATA.keywords[t.k];
      var title = name ? h('a', { href: CASE_DATA.lexicon_url + '#k-' + t.k, target: '_blank', rel: 'noopener', text: name + ' ↗' })
        : h('span', { text: t.k + '（观察中）' });
      var ev = String(t.evidence || '');
      var evidence = h('div', null,
        h('p', { class: 'decomp-evidence', text: '“' + ev + '”' }),
        ev.length > 95 ? h('details', null, h('summary', { text: '展开完整依据' }), h('p', { class: 'decomp-evidence', text: '“' + ev + '”' })) : null);
      group.append(h('div', { class: 'decomp-item' },
        h('div', { class: 'decomp-top' }, title, h('code', { text: t.k }),
          h('span', { class: 'decomp-level' + (t.level === '明写' ? ' explicit' : ''), text: t.level })),
        evidence));
    });
    p.append(group);
  });
}
